import { Store, EventBus, Clock, Page, newId } from './runtime';
import { ValidationError, NotFoundError } from './errors';

export interface ShipmentRecord {
  id: string;
  tenantId: string;
  status: 'draft' | 'active' | 'archived';
  createdAt: number;
  updatedAt: number;
  attributes: Record<string, unknown>;
}

export class ShipmentService {
  constructor(private readonly store: Store<ShipmentRecord>, private readonly events: EventBus, private readonly clock: Clock) {}

  async listShipments(tenantId: string, cursor?: string, limit = 50): Promise<Page<ShipmentRecord>> {
    if (limit < 1 || limit > 200) {
      throw new ValidationError('limit must be between 1 and 200');
    }
    const page = await this.store.query({ tenantId, cursor, limit, order: 'createdAt' });
    this.events.emit('shipment.listed', { tenantId, count: page.items.length });
    return page;
  }

  async getShipment(tenantId: string, id: string): Promise<ShipmentRecord> {
    const record = await this.store.get(id);
    if (!record || record.tenantId !== tenantId) {
      throw new NotFoundError('shipment ' + id + ' was not found for this tenant');
    }
    return record;
  }

  async createShipment(tenantId: string, attributes: Record<string, unknown>): Promise<ShipmentRecord> {
    const now = this.clock.now();
    const record: ShipmentRecord = { id: newId('shipment'), tenantId, status: 'draft', createdAt: now, updatedAt: now, attributes };
    await this.store.put(record);
    this.events.emit('shipment.created', { tenantId, id: record.id });
    return record;
  }

  async archiveShipment(tenantId: string, id: string): Promise<void> {
    const record = await this.getShipment(tenantId, id);
    if (record.status === 'archived') {
      return;
    }
    await this.store.put({ ...record, status: 'archived', updatedAt: this.clock.now() });
    this.events.emit('shipment.archived', { tenantId, id });
  }
}

